/**
 * Type definitions for human-names
 * Base mondiale de 17000+ prénoms
 */

declare module 'human-names' {
    /**
     * Liste complète des prénoms (17000+)
     */
    export const allFirstNames: string[];
    
    /**
     * Prénoms masculins
     */
    export const maleFirstNames: string[];
    
    /**
     * Prénoms féminins
     */
    export const femaleFirstNames: string[];
    
    /**
     * Noms de famille
     */
    export const allLastNames: string[];
    
    /**
     * Suffixes (Jr., Sr., III, etc.)
     */
    export const allNameSuffixes: string[];
    
    /**
     * Titres (Mr., Mrs., Dr., etc.)
     */
    export const allNameTitles: string[];
}
